"""Review the whole source, native reconstruction and real emulator side by side."""
from pathlib import Path
import json,hashlib
A=Path(__file__).resolve().parent;G=A.parents[1]
rows=[]
def add(phase,title,objective,source,native,group,key,tiles,cut=None):
 rows.append(dict(phase=phase,title=title,objective=objective,source=source,native=native,group=group,key=key,tiles=tiles,cut=cut))
e=json.loads((A/'early/geometry.json').read_text())
add('3','Rua da igreja ao galpão','Abrir caminho por2.560px; a igreja acompanha a escolha da bomba.','early/source/03-street.png','early/03-street/map-native.png','early','03',e['street']['tiles'],'early/03-street/sprites-8x8.png')
add('4','Interior do galpão','Eliminar20insetos e preparar abrigo para os civis.','early/source/04-warehouse-v2.png','early/04-warehouse/map-native.png','early','04',e['warehouse']['tiles'],'early/04-warehouse/sprites-8x8.png')
r=json.loads((G/'art/campaign-routes-v1/export.json').read_text())
for key,phase,title,goal in [('06a','6A','Esgotos após o resgate','Escoltar Dinorah por3.072px.'),('06b','6B','Esgotos sob pressão','Escoltar Dinorah, liberar2válvulas e romper2portões.'),('12','12','Oficinas do estaleiro','Escoltar Dinorah até o sindicato; sua sobrevivência afeta a etapa final.')]:
 add(phase,title,goal,'routes/source/'+key+'-complete.png','routes/'+key+'-native-complete.png','escorts',key,r[key]['tiles'])
f=json.loads((G/'art/campaign-factory-v1/geometry.json').read_text()) if (G/'art/campaign-factory-v1/geometry.json').exists() else {}
add('9','Rua industrial','Abrir caminho por2.560px até a fábrica.','factory/source/street-cycle1-complete.png','factory/street-native.png','factory','9',627)
for p,goal in [('10','Destruir10ninhos.'),('11','Liberar3válvulas; o calor atrai os insetos e abre a rota aos foguetes.')]:add(p,'Interior da fábrica',goal,'factory/source/factory-cycle1-complete.png','factory/factory-native.png','factory',p,f.get('tiles','—'))
launch=json.loads((A/'launch/geometry.json').read_text())
for p,title,goal,fire in [('14','Energia do estaleiro','Ativar5geradores.',False),('15','Rádio e ignição','Proteger o rádio por120s; o estaleiro entra em chamas.',False),('16','Escorpião','Derrotar o chefe que emerge do fogo.',True)]:
 add(p,title,goal,('launch/source/16-spaceport-fire.png' if fire else '../visual-composition-fixes-v1/launch/cycle-2/source/14-15-station-circuit.png'),'launch/previews/'+('16-fire-native-reconstructed.png' if fire else '14-15-normal-native-reconstructed.png'),'launch',p,launch['fire_tiles' if fire else 'normal_tiles'])
# Resistance uses the same physical settlement/room across narrative variants.
if (A/'resistance/geometry.json').exists():
 res=json.loads((A/'resistance/geometry.json').read_text())
else:res={}
for p,title,goal,src,nat in [('7','Favela — O Último Chão','Recolher5cargas e levá-las ao depósito.','07-08-favela.png','native/favela/map-native.png'),('8','Favela comprometida','Eliminar3transmissores e conter o enxame.','07-08-favela.png','native/favela/map-native.png'),('13A','Sindicato — Dinorah viva','Eliminar30insetos; Dinorah prepara recursos e participa do final.','13-union.png','native/union/alive-native.png'),('13B','Sindicato — Dinorah morta','Eliminar45insetos; a perda permanece na história.','13-union.png','native/union/dead-native.png')]:add(p,title,goal,('../visual-composition-fixes-v1/resistance/cycle-1/source/07-08-favela-calm.png' if p in ('7','8') else '../visual-composition-fixes-v1/resistance/cycle-2/source/13B-memorial.png' if p=='13B' else 'resistance/source/'+src),'resistance/'+nat,'resistance',p,res.get('favela_tiles' if p in ('7','8') else 'union_tiles','—'),'resistance/native/'+('favela' if p in ('7','8') else 'union')+'/sprites-8x8.png')
order=['3','4','6A','6B','7','8','9','10','11','12','13A','13B','14','15','16'];rows.sort(key=lambda r:order.index(r['phase']))
sha=hashlib.sha256((G/'out/release/Plaguefall.bin').read_bytes()).hexdigest()
for d in rows:
 prefix=G/'art/campaign-integrated-v1'/d['group']/'ntsc';report=prefix/'report.json'
 d['report']='../campaign-integrated-v1/'+d['group']+'/ntsc/report.json';d['verified']=False;d['load']=None
 if report.exists():
  info=json.loads(report.read_text());d['verified']=info.get('passed') and (info.get('rom_sha256') or info.get('romSHA256'))==sha
  if d['group']=='early':
   stage=next((s for s in info.get('stages',[]) if s['phase']==d['key']),None)
   if stage:d['load']=stage['checks'].get(d['key']+'/load',{}).get('details')
  elif d['group']=='escorts':d['load']=info.get('checks',{}).get(d['key']+'-stress')
  else:d['load']=info.get('nodes',{}).get(d['key'],{}).get('visible_maximum_stress')
 picture=d['key']+('-entrada.png' if d['group']=='escorts' else '-entry.png');d['capture']='../campaign-integrated-v1/'+d['group']+'/ntsc/'+picture+'?v='+sha[:12]
 movie=d['key']+('-traversal.mp4' if d['group']=='escorts' else '-playtest-1.mp4' if d['group']=='early' else '-playtest.mp4');d['movie']='../campaign-integrated-v1/'+d['group']+'/ntsc/'+movie+'?v='+sha[:12]
 for name in ('source','native'):assert (A/d[name]).exists(),d[name]
(A/'review-data.json').write_text(json.dumps({'rom_sha256':sha,'stages':rows},ensure_ascii=False,indent=2)+'\n')
html='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Plaguefall · Cenários completos</title><style>
*{box-sizing:border-box}body{margin:0;background:#101714;color:#e9e5d9;font:16px/1.5 system-ui}main{max-width:1300px;margin:auto;padding:30px}h1{font-size:36px;margin:0}h2{margin-bottom:6px}p{color:#bfcabb;max-width:1000px}nav{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0}button{font:inherit;color:#eee6d3;background:#23332b;border:1px solid #64735b;border-radius:5px;padding:8px 15px;cursor:pointer}button.active{color:#101714;background:#d6ad5e}a{color:#f4c773}.flow{display:flex;gap:12px;color:#e5be78;margin:20px 0;flex-wrap:wrap}.panel{background:#18251e;border:1px solid #4b5a49;border-radius:8px;padding:16px;margin:16px 0}.scroll{overflow:auto;background:#0c100e;border-radius:4px}.native{display:block;image-rendering:pixelated;min-width:100%;height:auto}.source{display:block;width:100%;height:auto}.split{display:grid;grid-template-columns:1fr 1fr;gap:18px}video,.frame{width:100%;image-rendering:pixelated;background:#080d0a}summary{cursor:pointer}.meta{font:13px monospace;overflow-wrap:anywhere;color:#a3b59f}pre{white-space:pre-wrap;font:13px monospace}.tag{display:inline-block;padding:4px 10px;border:1px solid #68765b;border-radius:4px;margin:3px 8px 8px 0}.small{font-size:13px}@media(max-width:800px){.split{display:block}main{padding:16px}}
</style><main><h1>Cenários completos · Plaguefall</h1><p>Revisão das fases3,4 e6–16. As fases1,2A/2B e5 foram preservadas. Cada ambiente parte de uma imagem inteira; os recortes arquitetônicos são convertidos para a paleta do console e remontados em tiles exatos.</p><div class="flow"><span>1 · Imagem inteira</span><span>→2 · Recortes e composição</span><span>→3 · Jogo e avaliação</span></div><p><a href="../../out/playtest/Plaguefall.bin">Baixar ROM de playtest</a> · <a href="../../out/release/Plaguefall.bin">Baixar campanha</a> · <a href="review-data.json">Dados da revisão</a> · <a href="README.md">Processo e limitações</a></p><p style="padding:14px;border:1px solid #bd7561;background:#402b26"><b>Correções de composição visual:</b> <a href="../visual-composition-fixes-v1/review.html">ver comparação antes/depois, decisões de revisão e playtests das13variações corrigidas</a>. A <a href="../visual-composition-audit-v1/review.html">auditoria original</a> permanece como histórico. Aprovação técnica e revisão visual são apresentadas separadamente.</p><nav id="nav"></nav><h2 id="title"></h2><p id="objective"></p><div id="status"></div><div class="panel"><h3>Imagem completa de origem</h3><img class="source" id="source"></div><div class="panel"><h3>Cenário nativo remontado — role para explorar a fase inteira</h3><div class="scroll"><img class="native" id="native"></div><p class="small">A imagem acima é reconstruída dos mesmos tiles usados naROM. Espelhamentos são exatos; nenhum tile é trocado por outro parecido.</p><details><summary>Tiles/sprites de composição</summary><img id="cuts" style="image-rendering:pixelated;max-width:100%"><p id="cutnote"></p></details></div><div class="panel split"><div><h3>Captura real do emulador</h3><img class="frame" id="capture"><video id="movie" controls muted loop preload="none"></video></div><div><h3>Avaliação da ROM</h3><p id="tested"></p><pre id="load"></pre><p><a id="report">Relatório de testes</a></p><p class="small">As provas de colisão e objetivos usam preparação isolada emRAM. Os vídeos de combate registram amostras automáticas; escoltas têm travessia com combate isolado. O equilíbrio fino precisa de uma campanha humana completa.</p></div></div><p class="meta">ROM: SHA</p></main><script>const data=DATA;let n=0;const el=id=>document.getElementById(id);function show(){const d=data[n];el('title').textContent='Fase '+d.phase+' · '+d.title;el('objective').textContent=d.objective;el('status').innerHTML='<span class="tag">'+d.tiles+' tiles de cenário</span><span class="tag">'+(d.verified?'Teste NTSC passou nestaROM':'Verificação em andamento')+'</span>';for(const k of ['source','native','capture'])el(k).src=d[k];el('movie').src=d.movie;el('movie').poster=d.capture;el('cuts').hidden=!d.cut;if(d.cut)el('cuts').src=d.cut;el('cutnote').textContent=d.cut?'Atlas de tiles8×8 reusados na composição.':'Os recortes arquitetônicos e seus retângulos de origem estão documentados no diretório deste ambiente.';el('tested').textContent=d.verified?'Cenário integrado naROM atual; relatório aprovado.':'A fonte e a imagem nativa estão disponíveis. Os testes destaROM ainda estão sendo concluídos.';el('load').textContent=d.load?JSON.stringify(d.load,null,2):'';el('report').href=d.report;document.querySelectorAll('nav button').forEach((b,i)=>b.classList.toggle('active',i===n))}data.forEach((d,i)=>{const b=document.createElement('button');b.textContent=d.phase;b.onclick=()=>{n=i;show()};el('nav').appendChild(b)});show()</script></html>'''.replace('DATA',json.dumps(rows,ensure_ascii=False)).replace('SHA</p>',sha+'</p>')
for a,b in [('por2.560px','por 2.560 px'),('Eliminar20insetos','Eliminar 20 insetos'),('por3.072px','por 3.072 px'),('liberar2válvulas','liberar 2 válvulas'),('romper2portões','romper 2 portões'),('Destruir10ninhos','Destruir 10 ninhos'),('Liberar3válvulas','Liberar 3 válvulas'),('Ativar5geradores','Ativar 5 geradores'),('por120s','por 120 s'),('Recolher5cargas','Recolher 5 cargas'),('Eliminar3transmissores','Eliminar 3 transmissores'),('Eliminar30insetos','Eliminar 30 insetos'),('Eliminar45insetos','Eliminar 45 insetos'),('fases3,4','fases 3,4'),('fases1,2A/2B e5','fases 1, 2A/2B e 5'),('naROM','na ROM'),('destaROM','desta ROM'),('nestaROM','nesta ROM'),('emRAM','em RAM'),('tiles8×8','tiles 8×8')]:html=html.replace(a,b)
(A/'review.html').write_text(html)
print('Review published,',len(rows),'variants;',sum(r['verified'] for r in rows),'current NTSC reports.')
